"""Nine calculators added Oct 2026 from Ahrefs demand: factoring (21k/mo KD0), markup (17k KD6), roof
replacement cost (1.7k KD0), pool loan (1.1k KD0), fence cost (1.1k KD4), generator sizing (900 KD14),
solar loan (500 KD4), equipment lease vs buy (400 KD5), HVAC financing (60 KD0 + 'ac financing calculator').
Each page: working JS widget, how-to-use, worked example, what it leaves out, FAQ, links to its money page and
guide. Cost ranges are typical national ranges; users are told to get local quotes."""
from common import *
from tools import calc_widget, CALC_JS

HOME = ("Home", "/")
TOOLS = ("Tools", "/tools/")
NOTE = "<p class='note'>Illustrative only. Not an offer of credit, a quote or financial advice. Lenders and contractors set real prices and rates.</p>"

def out(rows):
    return "<dl>" + "".join(f"<div><dt>{esc(k)}</dt><dd id='{i}'>—</dd></div>" for k, i in rows) + "</dl>"

def inp(i, label, val, step=1, mn=0, mx=None, hint=None):
    h = f"<small>{esc(hint)}</small>" if hint else ""
    return f"<label for='{i}'><span class='row'><span>{esc(label)}</span>{h}</span><input type='number' id='{i}' value='{val}' step='{step}' min='{mn}'{f' max={mx}' if mx else ''}></label>"

def sel(i, label, opts, val):
    o = "".join(f"<option value='{v}'{' selected' if v == val else ''}>{esc(t)}</option>" for v, t in opts)
    return f"<label for='{i}'><span class='row'><span>{esc(label)}</span></span><select id='{i}'>{o}</select></label>"

JS_HEAD = "(function(){var usd=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});var usd2=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2});function v(id){var e=document.getElementById(id);return e?(+e.value||0):0;}function set(id,t){var e=document.getElementById(id);if(e)e.textContent=t;}function pct(x){return (Math.round(x*10)/10)+'%';}"
JS_TAIL = "document.querySelectorAll('.tool-card input,.tool-card select').forEach(function(el){el.addEventListener('input',calc);el.addEventListener('change',calc);});calc();})();"

# ------------------------------------------------------------------ 1. factoring calculator
FACTOR = dict(
    path="/tools/factoring-calculator/", crumbs=[HOME, TOOLS, ("Factoring calculator", "/tools/factoring-calculator/")],
    eyebrow="Invoice factoring calculator", h1="Factoring calculator: what invoice factoring really costs",
    title="Factoring Calculator | Invoice Factoring Cost & Effective APR",
    meta="Free factoring calculator: enter the invoice, advance rate, fee and days to payment to see your cash up front, the total fee, what you keep, and the effective annual rate.",
    answer="This invoice factoring calculator shows what you receive up front, what the factor keeps, and what the fee works out to as an effective annual rate, based on the invoice amount, retainage, advance rate, fee schedule and how long your customer takes to pay. It is built for construction invoices, where retainage is usually excluded from the advance and fees are charged per period outstanding.",
    role="contractor", need="Invoice factoring",
    widget=f"""<div class="tool-card"><div class="calc-inputs">
{inp('f-inv','Invoice amount (USD)',60000,500)}{inp('f-ret','Retainage withheld (%)',10,1,0,50,'Usually excluded from the advance')}{inp('f-adv','Advance rate (%)',85,1,50,100,'Often 70–90%')}
{inp('f-fee','Fee for first period (%)',2.5,0.1,0,15)}{inp('f-per','First period (days)',30,1,1,90)}{inp('f-inc','Fee per extra increment (%)',1,0.1,0,10)}{inp('f-incd','Increment (days)',10,1,1,30)}{inp('f-days','Days until customer pays',60,1,1,180)}{inp('f-other','Other fees (setup, wire, processing)',0,25)}
</div><div class="calc-out" aria-live="polite"><div><p class="eyebrow" style="color:var(--gold)">Cash up front</p><p class="big" id="f-cash">$0</p></div>
{out([("Factorable amount (after retainage)","f-base"),("Total fee","f-total"),("You receive in total","f-net"),("Fee as % of invoice","f-pct"),("Effective annual rate","f-apr")])}{NOTE}</div></div>
<h2 id="schedule">Cost by days outstanding</h2><div class="tbl"><table><thead><tr><th>Customer pays in</th><th class="num">Fee</th><th class="num">Fee % of invoice</th><th class="num">Effective annual rate</th></tr></thead><tbody id="f-table"></tbody></table></div>""",
    js=JS_HEAD + """
function feeFor(days){var fee=v('f-fee'),per=v('f-per'),inc=v('f-inc'),incd=v('f-incd');if(days<=per)return fee;return fee+Math.ceil((days-per)/incd)*inc;}
function calc(){var inv=v('f-inv'),base=inv*(1-v('f-ret')/100),cash=base*v('f-adv')/100,days=v('f-days'),fp=feeFor(days),fee=base*fp/100+v('f-other'),net=base-fee;
var apr=cash>0&&days>0?(fee/cash)*(365/days)*100:0;
set('f-cash',usd.format(cash));set('f-base',usd.format(base));set('f-total',usd.format(fee));set('f-net',usd.format(net));set('f-pct',pct(inv>0?fee/inv*100:0));set('f-apr',pct(apr));
var rows='';[30,45,60,75,90,120].forEach(function(d){var f=base*feeFor(d)/100+v('f-other');var a=cash>0?(f/cash)*(365/d)*100:0;rows+='<tr'+(d===days?' style="background:var(--surface)"':'')+'><td>'+d+' days</td><td class="num">'+usd.format(f)+'</td><td class="num">'+pct(inv>0?f/inv*100:0)+'</td><td class="num">'+pct(a)+'</td></tr>';});document.getElementById('f-table').innerHTML=rows;}
""" + JS_TAIL,
    prose="""<h2 id="how-to-use">How to use the factoring calculator</h2>
<ol><li><strong>Enter the invoice</strong> and the retainage percentage on the job; most factors exclude retainage from the advance, so the calculator advances against the invoice net of it.</li><li><strong>Enter the factor's terms</strong>: advance rate, the fee for the first period (often 30 days), and the fee per additional increment (often per 10 or 15 days). These come from the factor's quote; ask for them in writing.</li><li><strong>Enter the days until your customer actually pays</strong>, not the invoice terms. A net-30 GC that pays in 55 days costs you the 55-day fee.</li><li><strong>Add other fees</strong> (setup, wire, per-invoice processing) to see the real total.</li></ol>
<h2 id="reading-results">Reading the results</h2><p>The <strong>effective annual rate</strong> is the number most quotes hide. A 2.5% fee for 30 days sounds small; on money you had for 30 days it's about 30% annualized on the advance, and higher if fees stack. That's not a reason to avoid factoring; it's a reason to compare it with a line of credit for recurring gaps and to use it where speed and credit coverage matter more than cost. The table shows how the fee climbs the longer the customer takes, which is why factoring suits reliable-but-slow payers, not disputed invoices.</p>
<h2 id="example">Worked example</h2><p>A $60,000 progress invoice with 10% retainage factored at an 85% advance, 2.5% for 30 days plus 1% per 10 days: $54,000 is factorable, $45,900 arrives up front, and if the GC pays in 60 days the fee is about $2,970 (5.5% of the factorable amount), roughly 39% annualized on the cash advanced. If the GC pays in 30 days the fee drops to $1,350. Our guide to <a href="/blog/how-construction-invoice-factoring-works/">how construction invoice factoring works</a> walks through the full process, and the <a href="/contractor-business-loans/invoice-factoring/">construction invoice factoring</a> page covers recourse, lien waivers and how to compare factors.</p>
<h2 id="leaves-out">What the calculator leaves out</h2><ul><li>Recourse vs non-recourse terms and what happens on a dispute.</li><li>Monthly minimums and termination fees in a factoring contract.</li><li>Whether your subcontract's pay-when-paid clause affects the factor's willingness to buy the invoice.</li><li>The alternative cost of a <a href="/contractor-business-loans/line-of-credit/">line of credit</a> or <a href="/contractor-business-loans/working-capital/">working capital loan</a>, which the comparison on those pages covers.</li></ul>""",
    faqs=[("How is a factoring fee calculated?", "Usually as a percentage of the invoice (or the factorable amount after retainage) for the first period, often 30 days, plus a smaller percentage for each additional increment the invoice stays unpaid. Some factors use flat rates or tiered schedules; ask for the exact terms."), ("What is a typical factoring rate?", "Commonly quoted in the range of 1% to 5% per 30 days depending on volume, customer credit and industry. Construction tends to sit higher than general B2B because of retainage and dispute risk."), ("What is the effective APR of factoring?", "Because the fee is charged on money you hold for only weeks, the annualized cost is far higher than the headline percentage: a 2.5% fee for 30 days on the advance is roughly 30% annualized. The calculator shows this for your numbers."), ("Can I factor retainage?", "Usually not. Most factors exclude retainage because it isn't due until closeout and may be reduced by disputes. The calculator removes it from the advance for that reason."), ("Is factoring cheaper than a loan?", "Per dollar, a line of credit is usually cheaper if you qualify. Factoring wins on speed, on approval based on your customer's credit rather than yours, and when you only need to bridge occasional invoices.")],
    related=[("Construction invoice factoring", "/contractor-business-loans/invoice-factoring/"), ("How construction invoice factoring works", "/blog/how-construction-invoice-factoring-works/"), ("Construction line of credit", "/contractor-business-loans/line-of-credit/"), ("Working capital for contractors", "/contractor-business-loans/working-capital/")],
    cta_h="Compare factoring with other capital", cta_p="Tell us about the invoices and the gap. We match contractors with factors and lenders who work in your state.",
)

# ------------------------------------------------------------------ 2. markup / margin calculator
MARKUP = dict(
    path="/tools/markup-calculator/", crumbs=[HOME, TOOLS, ("Markup calculator", "/tools/markup-calculator/")],
    eyebrow="Markup and margin calculator", h1="Markup calculator: markup, margin and the price that covers overhead",
    title="Markup Calculator | Markup vs Margin for Contractors",
    meta="Free markup calculator: convert markup to margin and back, and build a contractor price from direct cost, overhead, contingency and target margin.",
    answer="This markup calculator does two things. The quick converter turns a markup percentage into the margin it produces (and back), which trips up many contractors: 25% margin on price is 33% markup on cost. The job pricing section builds a bid from direct cost, overhead recovery, contingency and target margin, and shows the price before and after any customer-financing dealer fee.",
    role="contractor", need="Working capital",
    widget=f"""<div class="tool-card"><div class="calc-inputs">
<h3 style="grid-column:1/-1;margin:0">Quick converter</h3>{inp('m-cost','Cost (USD)',10000,100)}{inp('m-markup','Markup on cost (%)',33.3,0.1,0,500)}{inp('m-margin','Or target margin on price (%)',25,0.1,0,99,'Edit either; the other updates')}
<h3 style="grid-column:1/-1;margin:12px 0 0">Job price build-up</h3>{inp('m-direct','Direct cost (materials, burdened labor, subs, permits)',22648,100)}{inp('m-oh','Overhead recovery (% of direct cost)',18,0.5,0,100,'Annual overhead ÷ annual direct costs')}{inp('m-cont','Contingency (%)',4,0.5,0,30)}{inp('m-days','Days until paid',45,1,0,180)}{inp('m-coc','Cost of capital (% per year)',18,0.5,0,60)}{inp('m-tm','Target margin on price (%)',25,0.5,0,80)}{inp('m-fee','Dealer fee if customer uses promo financing (%)',6,0.5,0,20)}
</div><div class="calc-out" aria-live="polite"><div><p class="eyebrow" style="color:var(--gold)">Price (cash)</p><p class="big" id="m-price">$0</p></div>
{out([("Converter: price at this markup","m-cprice"),("Converter: margin this markup produces","m-cmargin"),("Converter: markup for the target margin","m-cmarkup"),("Overhead","m-ohv"),("Cash-flow cost","m-cfv"),("Contingency","m-contv"),("Break-even","m-be"),("Gross profit at target margin","m-gp"),("Price if customer uses promo plan","m-pricefee")])}{NOTE}</div></div>""",
    js=JS_HEAD + """
var last='markup';document.getElementById('m-markup').addEventListener('input',function(){last='markup';});document.getElementById('m-margin').addEventListener('input',function(){last='margin';});
function calc(){var c=v('m-cost');var mk=v('m-markup'),mg=v('m-margin');if(last==='markup'){mg=mk/(100+mk)*100;document.getElementById('m-margin').value=Math.round(mg*10)/10;}else{mk=mg>=100?0:mg/(100-mg)*100;document.getElementById('m-markup').value=Math.round(mk*10)/10;}
set('m-cprice',usd.format(c*(1+mk/100)));set('m-cmargin',pct(mg));set('m-cmarkup',pct(mk));
var d=v('m-direct'),oh=d*v('m-oh')/100,cf=d*v('m-coc')/100*v('m-days')/365,ct=d*v('m-cont')/100,be=d+oh+cf+ct,tm=v('m-tm'),price=tm>=100?0:be/(1-tm/100),fee=v('m-fee');
set('m-ohv',usd.format(oh));set('m-cfv',usd.format(cf));set('m-contv',usd.format(ct));set('m-be',usd.format(be));set('m-price',usd.format(price));set('m-gp',usd.format(price-be));set('m-pricefee',usd.format(price*(1+fee/100)));}
""" + JS_TAIL,
    prose="""<h2 id="markup-vs-margin">Markup vs margin: why the difference costs contractors money</h2><p><strong>Markup</strong> is what you add to cost. <strong>Margin</strong> is the share of the price that is profit. A 25% markup on a $10,000 cost gives a $12,500 price, but the margin is only 20% ($2,500 of $12,500). To earn a 25% margin you need a 33.3% markup. Contractors who set "25% markup" believing they're earning 25% margin leave a fifth of their intended profit on the table on every job. The converter above makes the relationship explicit.</p>
<h2 id="how-to-use">How to use the job price build-up</h2><ol><li><strong>Direct cost</strong> is everything the job itself consumes: materials with waste, labor with burden (payroll taxes, workers' comp, insurance, PTO, often 25% to 40% on top of wages), subcontractors, equipment, dumpster, permits.</li><li><strong>Overhead recovery</strong> spreads the cost of running the company (office, trucks, insurance, sales, software, your salary) across jobs. Divide last year's overhead by last year's direct costs to get the percentage.</li><li><strong>Cash-flow cost</strong> is the interest on money you've spent before the customer pays, at your line-of-credit or loan rate.</li><li><strong>Contingency</strong> covers the surprises every job has.</li><li><strong>Target margin</strong> is applied on price, not cost, which is what the calculator does.</li><li><strong>Dealer fee</strong> shows what the price needs to be if the customer takes a promotional financing plan that charges you a fee; many contractors quote a cash price and a financed price.</li></ol>
<h2 id="example">Worked example</h2><p>Direct cost $22,648, overhead 18% ($4,077), 45 days to payment at an 18% cost of capital ($503), 4% contingency ($906): break-even about $28,100. At a 25% margin on price the bid is about $37,500; if the customer chooses a 0% plan with a 6% dealer fee, the financed price is about $39,750. Our guide to <a href="/blog/how-to-bid-construction-jobs/">how to bid construction jobs</a> walks through this build-up line by line, and <a href="/for-contractors/">contractor financing</a> explains dealer fees.</p>
<h2 id="leaves-out">What the calculator leaves out</h2><ul><li>Change-order pricing, which is where margin is often won or lost after the bid.</li><li>Taxes on profit and owner's compensation structure.</li><li>Whether your overhead percentage is current; recalculate it each year.</li><li>Market pricing: a bid can be correct and still too high for a given customer, which is where offering a monthly payment helps. See <a href="/blog/why-contractors-lose-jobs-without-financing/">why contractors lose jobs without financing</a>.</li></ul>""",
    faqs=[("What markup equals a 30% margin?", "About 42.9%. Markup = margin ÷ (1 − margin). The converter above does this for any number."), ("What is a typical contractor markup?", "It varies widely by trade and region. Many residential contractors target 20% to 35% gross margin on price after full direct costs and overhead, which corresponds to 25% to 54% markup on cost. Specialty and emergency work can carry more."), ("Should overhead be a percentage of direct cost or of price?", "Either works if you're consistent. This calculator recovers overhead as a percentage of direct cost, then applies margin on price, which is the most common contractor method."), ("Do I add the dealer fee to every bid?", "Only to jobs where the customer chooses a promotional plan that charges you a fee, and only where your lender agreement and state rules allow a different financed price. Many contractors quote both prices or absorb the fee on larger jobs."), ("Is contingency the same as profit?", "No. Contingency covers expected surprises (decking rot, weather days); profit is what's left after everything, including surprises. Budget both.")],
    related=[("How to bid construction jobs", "/blog/how-to-bid-construction-jobs/"), ("Contractor financing: offer customer financing", "/for-contractors/"), ("Working capital for contractors", "/contractor-business-loans/working-capital/"), ("Construction bid worksheet (PDF)", "/blog/how-to-bid-construction-jobs/")],
    cta_h="Close more bids with a monthly option", cta_p="Partner contractors present a payment next to the price. See how customer financing programs work.",
)

