HVAC = dict(
    path="/tools/hvac-financing-calculator/", crumbs=[HOME, TOOLS, ("HVAC financing calculator", "/tools/hvac-financing-calculator/")],
    eyebrow="HVAC financing calculator", h1="HVAC financing calculator: AC, furnace and heat pump payments per month",
    title="HVAC Financing Calculator | AC & Furnace Loan Payment Calculator",
    meta="Free HVAC financing calculator: enter the system quote, rebates, term and an example APR to see the monthly payment, total interest and amortization for an AC, furnace or heat pump.",
    answer="This HVAC financing calculator (it works as an AC financing calculator or furnace loan calculator too) estimates the monthly payment on an HVAC replacement financed over a fixed term using standard amortization. Enter the contractor's quote, subtract any rebates as a down payment, pick a term and an example APR, and it shows the payment, total interest and a full schedule with a term comparison.",
    role="homeowner", project="HVAC (AC, furnace, heat pump)",
    widget=calc_widget(9500, 1000, 60000, 250, (24, 36, 60, 84, 120), 60, "10.99", with_down=True, amount_label="HVAC quote (USD)"), js=CALC_JS,
    prose="""<h2 id="how-to-use">How to use the HVAC financing calculator</h2><ol><li><strong>Enter the quote</strong> for the system you're considering, including ductwork, thermostat, permits and haul-away if they're in it. Run it twice: once for the standard-efficiency option and once for the high-efficiency one, so the upgrade shows as a monthly difference.</li><li><strong>Enter rebates or a down payment</strong> in the down payment field; utility rebates for efficient equipment reduce the amount financed.</li><li><strong>Pick a term.</strong> HVAC loans commonly run three to ten years. A furnace or AC with a 15-year life should carry a loan that ends well before then.</li><li><strong>Enter an example APR.</strong> Lenders quote the real rate after an application; try a few values, and see <a href="/hvac-financing/bad-credit-hvac-financing/">HVAC financing with bad credit</a> if your score is on the lower side.</li></ol>
<h2 id="reading-results">Reading the results</h2><p>A $9,500 system over 60 months at 10.99% is about $206 a month and roughly $2,900 in interest; over 120 months the payment drops to about $131 but interest roughly doubles. The term comparison table shows every option. If a contractor's promotional plan shows a lower figure, check whether it's deferred interest and whether the price is the same for cash; the <a href="/blog/furnace-and-ac-replacement-financing/">furnace and AC replacement financing</a> guide explains both.</p>
<h2 id="what-hvac-costs">What HVAC replacements typically cost</h2><p>A furnace alone is often several thousand dollars installed; an AC condenser and matching coil several thousand more; a full split system or heat pump commonly runs well into five figures, with ductwork, electrical and gas-line work on top. Two or three quotes on the same tonnage and efficiency, with model numbers listed, are the only reliable way to know your local price. Our <a href="/hvac-financing/">HVAC financing</a> page compares the ways to pay with example payments.</p>
<h2 id="leaves-out">What the calculator leaves out</h2><ul><li>Origination fees, which some lenders deduct from the loan; compare APR including fees.</li><li>Promotional-plan mechanics (deferred interest, dealer fees in the price).</li><li>Energy savings from a more efficient system, which can partly offset the payment but shouldn't be counted on to cover it.</li><li>Manufacturer financing programs (Trane, Carrier and others through bank partners), which may offer different terms on specific equipment.</li></ul>""",
    faqs=[("How much is HVAC financing per month?", "As an illustration, $9,500 over 60 months at 10.99% APR is about $206 a month; over 120 months about $131. Your quote, APR and term decide it."), ("Can I use this as an AC financing calculator?", "Yes. Enter the AC quote and run the numbers; the arithmetic is the same for an AC, a furnace or a heat pump."), ("What credit score do I need for HVAC financing?", "Each lender sets its own criteria. Stronger credit means more choices and lower APRs; some lenders consider lower scores at higher rates or with a co-applicant."), ("Do HVAC loans have prepayment penalties?", "Most unsecured loans don't, but some promotional plans have conditions. Check the agreement before signing."), ("Should I finance the high-efficiency system?", "Run both quotes through the calculator and compare the monthly difference with the contractor's estimated energy saving. In hot or cold climates with high usage the upgrade often pays; in mild climates it may not.")],
    related=[("HVAC financing", "/hvac-financing/"), ("HVAC financing with bad credit", "/hvac-financing/bad-credit-hvac-financing/"), ("Furnace and AC replacement financing", "/blog/furnace-and-ac-replacement-financing/"), ("Roof financing calculator", "/tools/roof-financing-calculator/")],
    cta_h="See real HVAC financing offers", cta_p="One request reaches lenders who fund HVAC work in your state. Soft-inquiry options shown first.",
)

